  fs.mkdirSync(PS_TMP_DIR, { recursive: true });
  const tmp = path.join(PS_TMP_DIR, `job-${process.pid}-${crypto.randomBytes(8).toString('hex')}.ps1`);
  await fs.promises.writeFile(tmp, wrapPowerShellScript(script), 'utf8');
