/**
 * Backfill inactiveSince for older records.
 */
function backfillInactiveSince(hosts) {
  for (const h of Object.values(hosts)) {
    if (!h || typeof h !== 'object') continue;
    if (h.lastStatus === 'Ativo') {
      h.inactiveSince = null;
      h.consecutiveInactiveScans = 0;
      continue;
    }
    if (h.lastStatus === 'Inativo') {
      h.recoveredActiveSince = null;
      h.recoveredActiveSinceIso = null;
    }
    if (h.lastStatus === 'Inativo' && h.inactiveSince == null) {
      h.inactiveSince = h.lastSeen != null
        ? h.lastSeen
        : (h.lastChecked || h.firstSeen || Date.now());
    }
    if (h.consecutiveInactiveScans == null) {
      h.consecutiveInactiveScans = h.lastStatus === 'Inativo' ? 1 : 0;
    }
  }
  return hosts;
}

/**
 * Preenche recoveredActiveSince em hosts que voltaram a ativo antes da feature existir.
 */
function backfillRecoveredActiveSince(hosts, scans) {
  if (!Array.isArray(scans) || scans.length < 2) return hosts;
  const latest = scans[scans.length - 1];
  const previous = scans[scans.length - 2];
  const scanGap = Math.max(0, (latest.at || 0) - (previous.at || 0));
  const minGap = Math.max(scanGap * 2, 60 * 60 * 1000);

  for (const h of Object.values(hosts)) {
    if (!h || h.lastStatus !== 'Ativo' || h.recoveredActiveSince != null) continue;
    if (h.lastSeen == null || h.previousLastSeen == null) continue;
    const gap = h.lastSeen - h.previousLastSeen;
    if (gap <= minGap) continue;
    h.recoveredActiveSince = h.lastSeen;
    h.recoveredActiveSinceIso = new Date(h.lastSeen).toISOString();
  }
  return hosts;
}

function normalizeHistory(parsed) {
  if (!parsed || typeof parsed !== 'object') {
    return { version: 4, hosts: {}, scans: [] };
  }

  const hosts = backfillInactiveSince(
    parsed.hosts && typeof parsed.hosts === 'object' ? parsed.hosts : {}
  );
  let scans = Array.isArray(parsed.scans) ? parsed.scans : [];

  if (scans.length === 0 && Object.keys(hosts).length > 0) {
    let at = null;
    for (const h of Object.values(hosts)) {
      const ts = h.lastChecked || h.lastSeen || h.firstSeen || h.inactiveSince;
      if (ts != null && (at == null || ts < at)) at = ts;
    }
    at = at || Date.now();
    const active = Object.values(hosts).filter(h => h.lastStatus === 'Ativo').length;
    scans = [{
      id: `scan_baseline_${at}`,
      at,
      atIso: new Date(at).toISOString(),
      target: null,
      total: Object.keys(hosts).length,
      active,
      inactive: Object.keys(hosts).length - active,
      updated: Object.keys(hosts).length,
      baseline: true,
      remainedIdle: 0,
      newlyIdle: Object.keys(hosts).length - active,
      recoveredActive: 0
    }];
  }

  backfillRecoveredActiveSince(hosts, scans);

  return { version: 4, hosts, scans };
}

