    ports: Array.isArray(host.ports) && host.ports.length ? host.ports : (base.ports || [])
  };

  if (!next.firstScanId) next.firstScanId = scanId;

  if (isActive) {
    next.previousLastSeen = base.lastSeen || null;
    next.lastSeen = now;
    next.firstSeen = base.firstSeen || now;
    next.timesSeenActive = (base.timesSeenActive || 0) + 1;
    next.lastActiveScanId = scanId;
    next.inactiveSince = null;
    next.consecutiveInactiveScans = 0;
    if (wasInactive) {
      next.recoveredActiveSince = now;
      next.recoveredActiveSinceIso = new Date(now).toISOString();
