      next.recoveredActiveSinceIso = base.recoveredActiveSinceIso || new Date(base.recoveredActiveSince).toISOString();
    }
  } else {
    next.recoveredActiveSince = null;
    next.recoveredActiveSinceIso = null;
  }

  if (!isActive) {
    if (wasInactive && base.inactiveSince != null) {
      next.inactiveSince = base.inactiveSince;
      next.consecutiveInactiveScans = (base.consecutiveInactiveScans || 1) + 1;
    } else if (wasActive || base.lastSeen != null) {
      next.inactiveSince = base.lastSeen || now;
      next.consecutiveInactiveScans = 1;
    } else {
      next.inactiveSince = now;
      next.consecutiveInactiveScans = 1;
    }
  }

  return next;
}

