/**
 * Relatório PDF Inventário UNESP — tema LinkWare
 */
const PDFDocument = require('pdfkit');
const { createPdfContext } = require('./canonReportPdf');
const { C, fmtDatePt, fmtReportId } = require('./canonReportTheme');

function generateInventoryPdf(items, stats = {}, meta = {}) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ margin: 0, size: 'A4', bufferPages: true });
    const chunks = [];
    doc.on('data', (c) => chunks.push(c));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    const ctx = createPdfContext(doc);
    ctx._topSubtitle = 'Inventário Corporativo · Complexo UNESP';
    ctx.newPage(true);

    ctx.drawMetaBox('NetScan Canon — Inventário UNESP', [
      ['Data/Hora', fmtDatePt(new Date().toISOString())],
      ['Última varredura', fmtDatePt(meta.lastScanAt)],
      ['Relatório', fmtReportId(meta.lastScanAt)],
      ['Operador', process.env.USERNAME || process.env.USER || '—']
    ]);

    ctx.drawStatCards([
      { label: 'Total', value: stats.total || 0 },
      { label: 'Online', value: stats.online || 0, color: C.pass },
      { label: 'Offline', value: stats.offline || 0, color: C.muted },
      { label: 'Ausente', value: stats.absent || 0, color: C.info },
      { label: 'Inacessível', value: stats.inaccessible || 0, color: C.fail },
      { label: 'Usuários', value: stats.connectedUsers || 0, color: C.info }
    ]);

    if (stats.total) {
      const onlinePct = Math.round(((stats.online || 0) / stats.total) * 100);
      ctx.drawProgressBar('Máquinas online', onlinePct, C.pass);
    }

    ctx.drawSectionTitle('Equipamentos inventariados');
    const cols = [52, 78, 58, 82, 48, 48, 95];
    const headers = ['IP', 'Hostname', 'Usuário', 'Nome', 'Status', 'SO', 'Departamento'];

    function drawHdr() {
      const y = doc.y;
      doc.rect(ctx.PAGE.left, y, ctx.PAGE.width, 16).fill(C.brand);
      doc.fillColor('#fff').fontSize(7);
      let x = ctx.PAGE.left + 3;
      headers.forEach((h, i) => { doc.text(h, x, y + 4, { width: cols[i] }); x += cols[i]; });
      doc.y = y + 18;
    }

    drawHdr();
    (items || []).forEach((item, i) => {
      if (doc.y > ctx.PAGE.contentBottom) {
        ctx.newPage(false);
        drawHdr();
      }
      const y = doc.y;
      if (i % 2 === 0) doc.rect(ctx.PAGE.left, y, ctx.PAGE.width, 14).fill('#f1f5f9');
      const stColor = item.status === 'Online' ? C.pass
        : item.status === 'Offline' ? C.muted
          : item.status === 'Ausente' ? C.info
            : C.fail;
      const vals = [item.ip, item.hostname, item.adUser, item.adUserFullName, item.status, item.os, item.department];
      let x = ctx.PAGE.left + 3;
      vals.forEach((v, ci) => {
        doc.fillColor(ci === 4 ? stColor : C.body).fontSize(6.5).text(String(v || '—').slice(0, ci === 6 ? 50 : 22), x, y + 3, { width: cols[ci] });
        x += cols[ci];
      });
      doc.y = y + 14;
    });

    ctx.stampFooters('Inventário UNESP');
    doc.end();
  });
}

module.exports = { generateInventoryPdf };

const express = require('express');
const {
  getInventory,
  getAllInventoryItems,
  syncInventoryFromScanAsync,
  resolveInventoryAdUsers,
  computeStats,
  loadStore,
  saveStore,
  buildInventoryContext,
  enrichAllItems,
  detectFlags
} = require('./inventory');
const { generateInventoryXlsx } = require('./inventoryXlsx');
const { generateInventoryPdf } = require('./inventoryPdf');
const { generateInventoryCsv } = require('./inventoryCsv');

function mountInventoryRoutes(app, ctx = {}) {
  const router = express.Router();
  const getResults = () => (typeof ctx.getLastScanSnapshot === 'function' ? ctx.getLastScanSnapshot() : []);

  if (typeof ctx.requireModalsAuth === 'function') {
    router.use(ctx.requireModalsAuth);
  }

  router.get('/', (req, res) => {
    try {
      res.json(getInventory(req.query));
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  router.get('/stats', (req, res) => {
    try {
      const items = getAllInventoryItems();
      res.json({ ok: true, stats: computeStats(items), lastScanAt: items[0]?.lastScanAt || null });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  router.post('/sync', async (req, res) => {
    try {
      const results = req.body?.results || getResults();
      if (!results.length) {
        const store = loadStore();
        const ctx = buildInventoryContext();
        const adResolve = await resolveInventoryAdUsers(store, ctx, req.body?.meta?.adResolveOptions || {});
        const items = detectFlags(enrichAllItems(Object.values(store.items), ctx));
        store.items = Object.fromEntries(items.map((i) => [i.ip, i]));
        saveStore(store);
        return res.json({
          ok: true,
          mode: 'ad-only',
          added: 0,
          updated: 0,
          absent: 0,
          removed: 0,
          adUsersResolved: adResolve.resolved || 0,
          adUsersScanned: adResolve.scanned || 0,
          macEnriched: adResolve.macFilled || 0,
          snmpMacFilled: adResolve.snmpMacFilled || 0,
          snmpEntries: adResolve.snmpEntries || 0,
          portsEnriched: adResolve.portsFilled || 0,
          firstSeenBackfilled: adResolve.firstSeenFilled || 0,
          adSnapshot: adResolve.snapshot || null,
          total: items.length,
          lastScanAt: store.lastScanAt,
          lastScanTarget: store.lastScanTarget,
          message: 'Sem varredura em memória; inventário persistido atualizado (AD, MAC, portas, datas).'
        });
      }
      const data = await syncInventoryFromScanAsync(results, req.body?.meta || {});
      res.json(data);
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  router.post('/resolve-ad-users', async (req, res) => {
    try {
      const store = loadStore();
      const ctx = buildInventoryContext();
      const result = await resolveInventoryAdUsers(store, ctx, req.body?.options || {});
      const items = detectFlags(enrichAllItems(Object.values(store.items), ctx));
      store.items = Object.fromEntries(items.map((i) => [i.ip, i]));
      saveStore(store);
      res.json({ ok: true, ...result, total: items.length });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  router.post('/export-xlsx', async (req, res) => {
    try {
      const items = getAllInventoryItems();
      if (!items.length) return res.status(400).json({ error: 'Inventário vazio. Execute uma varredura e sincronize.' });
      const stats = computeStats(items);
      const buffer = await generateInventoryXlsx(items, stats, { lastScanAt: items[0]?.lastScanAt });
      const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
      res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      res.setHeader('Content-Disposition', `attachment; filename="inventario-unesp-${stamp}.xlsx"`);
      res.send(buffer);
    } catch (err) {
      res.status(500).json({ error: err.message || 'Falha ao gerar Excel.' });
    }
  });

  router.post('/export-pdf', async (req, res) => {
    try {
      const items = getAllInventoryItems();
      if (!items.length) return res.status(400).json({ error: 'Inventário vazio.' });
      const stats = computeStats(items);
      const pdf = await generateInventoryPdf(items, stats, { lastScanAt: items[0]?.lastScanAt });
      const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="inventario-unesp-${stamp}.pdf"`);
      res.send(pdf);
    } catch (err) {
      res.status(500).json({ error: err.message || 'Falha ao gerar PDF.' });
    }
  });

  router.post('/export-csv', (req, res) => {
    try {
      const items = getAllInventoryItems();
      if (!items.length) return res.status(400).json({ error: 'Inventário vazio.' });
      const stats = computeStats(items);
      const csv = generateInventoryCsv(items, stats);
      const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
      res.setHeader('Content-Type', 'text/csv; charset=utf-16le');
      res.setHeader('Content-Disposition', `attachment; filename="inventario-unesp-${stamp}.csv"`);
      res.send(csv);
    } catch (err) {
      res.status(500).json({ error: err.message || 'Falha ao gerar CSV.' });
    }
  });

  app.use('/api/inventory', router);
}

module.exports = { mountInventoryRoutes };

