function ensureDataDir() {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
}

function loadPlatformConfig() {
  ensureDataDir();
  if (!fs.existsSync(CONFIG_FILE)) {
    const cfg = { ...DEFAULT_CONFIG, updatedAt: new Date().toISOString() };
    fs.writeFileSync(CONFIG_FILE, JSON.stringify(cfg, null, 2), 'utf8');
    return cfg;
  }
  try {
    const raw = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8'));
    return {
      ...DEFAULT_CONFIG,
      ...raw,
      features: { ...DEFAULT_CONFIG.features, ...(raw.features || {}) },
      schedule: { ...DEFAULT_CONFIG.schedule, ...(raw.schedule || {}) },
      rbac: { ...DEFAULT_CONFIG.rbac, ...(raw.rbac || {}) },
      nac: { ...DEFAULT_CONFIG.nac, ...(raw.nac || {}) }
    };
  } catch {
    return { ...DEFAULT_CONFIG, updatedAt: new Date().toISOString() };
  }
}

function savePlatformConfig(config) {
  ensureDataDir();
  const merged = { ...loadPlatformConfig(), ...config, updatedAt: new Date().toISOString() };
  const tmp = `${CONFIG_FILE}.tmp`;
