  return site || cfg.sites?.[0] || DEFAULT_CONFIG.sites[0];
}

module.exports = {
  CONFIG_FILE,
  DEFAULT_CONFIG,
  loadPlatformConfig,
  savePlatformConfig,
  isFeatureEnabled,
  getActiveSite
};

