const execFileAsync = promisify(execFile);

const OID = {
  ipNetToMediaPhysAddress: '1.3.6.1.2.1.4.22.1.2'
};

function normalizeMacHex(mac) {
  if (!mac) return null;
  const hex = String(mac).replace(/[^a-fA-F0-9]/g, '').toLowerCase();
  if (hex.length !== 12) return null;
  return hex.match(/.{2}/g).join('-').toUpperCase();
}

function macFromSnmpValue(val) {
  if (val == null) return null;
  if (Buffer.isBuffer(val)) {
    const slice = val.length >= 6 ? val.slice(0, 6) : val;
    return normalizeMacHex([...slice].map((b) => b.toString(16).padStart(2, '0')).join(''));
  }
  if (typeof val === 'string') return normalizeMacHex(val);
  return null;
}

function ipFromNetToMediaOid(oid, base) {
  const prefix = `${base}.`;
  if (!String(oid).startsWith(prefix)) return null;
  const parts = oid.slice(prefix.length).split('.').map((x) => parseInt(x, 10));
  if (parts.length < 5) return null;
  const octets = parts.slice(-4);
  if (octets.some((n) => Number.isNaN(n) || n < 0 || n > 255)) return null;
  return octets.join('.');
}

function snmpSession(ip, community, timeoutMs, retries = 1) {
  return snmp.createSession(ip, community || 'public', {
    timeout: timeoutMs || 3500,
    retries,
    version: snmp.Version2c
  });
}

function snmpWalk(session, oid, maxRepetitions = 40) {
  return new Promise((resolve) => {
    const rows = [];
    session.subtree(
      oid,
      maxRepetitions,
      (varbinds) => {
        for (const vb of varbinds || []) {
          if (snmp.isVarbindError(vb)) continue;
          rows.push({ oid: vb.oid, value: vb.value });
        }
      },
      (err) => {
        const errText = err ? String(err) : '';
        if (err && !/NoSuch|endOfMib|RequestTimedOut|not found/i.test(errText)) {
          return resolve({ err: errText, rows, tooBig: /TooBig/i.test(errText) });
        }
        resolve({ err: null, rows, tooBig: false });
      }
    );
  });
}

async function snmpWalkAdaptive(session, oid, maxRepetitions = 40) {
  const attempts = [...new Set([maxRepetitions, 25, 15, 10, 5, 2].filter((n) => n > 0))].sort((a, b) => b - a);
  let last = { err: 'SNMP walk failed', rows: [], tooBig: false };
  for (const maxRep of attempts) {
    last = await snmpWalk(session, oid, maxRep);
    if (!last.err || !last.tooBig) return last;
  }
  return last;
}

async function queryIpNetToMedia(ip, community, timeoutMs = 4000) {
  const session = snmpSession(ip, community, timeoutMs);
  try {
    const walk = await snmpWalkAdaptive(session, OID.ipNetToMediaPhysAddress, 40);
    const map = new Map();
    for (const row of walk.rows || []) {
      const hostIp = ipFromNetToMediaOid(row.oid, OID.ipNetToMediaPhysAddress);
      const mac = macFromSnmpValue(row.value);
      if (!hostIp || !mac || hostIp === '0.0.0.0') continue;
      map.set(hostIp, mac);
    }
    return { ok: true, ip, count: map.size, map, error: walk.err || null };
  } catch (err) {
    return { ok: false, ip, count: 0, map: new Map(), error: err.message || String(err) };
  } finally {
    try { session.close(); } catch { /* ignore */ }
  }
}

async function discoverDefaultGateways() {
  const gateways = new Set();
  if (process.platform === 'win32') {
    try {
      const { stdout } = await execFileAsync('route', ['print', '0.0.0.0'], {
        windowsHide: true,
        timeout: 8000,
        maxBuffer: 512 * 1024,
        encoding: 'utf8'
      });
      for (const line of String(stdout || '').split(/\r?\n/)) {
        const m = line.match(/^\s*0\.0\.0\.0\s+\S+\s+(\d+\.\d+\.\d+\.\d+)/);
        if (m && m[1] !== '0.0.0.0') gateways.add(m[1]);
      }
    } catch {
      // ignore
    }
  }
  try {
    const { stdout } = await execFileAsync('ip', ['route', 'show', 'default'], {
      timeout: 5000,
      encoding: 'utf8'
    });
    for (const line of String(stdout || '').split(/\r?\n/)) {
      const m = line.match(/default via (\d+\.\d+\.\d+\.\d+)/);
      if (m) gateways.add(m[1]);
    }
  } catch {
    // ignore
  }
  return [...gateways];
}

function collectSnmpTargets(options = {}) {
  const loopCfg = loopDetection.getConfig();
  const vlanMap = loadVlanMap();
  const seen = new Set();
  const targets = [];

  const add = (ip, meta = {}) => {
    const safeIp = String(ip || '').trim();
    if (!safeIp || !/^\d+\.\d+\.\d+\.\d+$/.test(safeIp) || seen.has(safeIp)) return;
    seen.add(safeIp);
    targets.push({
      ip: safeIp,
      name: meta.name || safeIp,
      community: meta.community || loopCfg.community || 'public',
      source: meta.source || 'config'
    });
  };

  for (const sw of loopDetection.listSwitches() || []) {
    add(sw.ip, {
      name: sw.name || sw.ip,
      community: sw.community || loopCfg.community,
      source: 'loop-monitor'
    });
  }

  const snmpCfg = vlanMap?.snmp;
  if (snmpCfg?.enabled !== false && Array.isArray(snmpCfg?.switches)) {
    for (const entry of snmpCfg.switches) {
      if (typeof entry === 'string') add(entry, { community: snmpCfg.community, source: 'vlan-map' });
      else if (entry && entry.ip) {
        add(entry.ip, {
          name: entry.name,
          community: entry.community || snmpCfg.community,
          source: 'vlan-map'
        });
      }
    }
  }

  for (const ip of options.extraTargets || []) add(ip, { source: 'manual' });

  return targets;
}

