const path = require('path');
const {
  listShares,
  listChildren,
  getPathAcl,
  listConfiguredServers
} = require(path.join(__dirname, '..', 'fileShareAudit'));

function assert(name, cond, detail) {
  const pass = !!cond;
  console.log(`${pass ? 'PASS' : 'FAIL'} | ${name} | ${String(detail || '').slice(0, 220)}`);
  return { name, pass, detail: String(detail || '') };
}

(async () => {
  const results = [];
  const host = '200.145.131.105';

  results.push(assert('module loads', true, 'ok'));
  const servers = listConfiguredServers();
  results.push(assert('servers configured', servers.ok && servers.servers.some((s) => s.host === host), JSON.stringify(servers.servers)));

  let shares;
  try {
    shares = await listShares(host, {});
  } catch (e) {
    shares = { ok: false, error: e.message, shares: [] };
  }
  results.push(assert(
    'listShares sem ENAMETOOLONG',
    !/ENAMETOOLONG|spawn/i.test(JSON.stringify(shares)),
    shares.ok ? `count=${shares.count}` : shares.error
  ));
  results.push(assert('listShares ok', !!shares.ok, shares.ok ? `method=${shares.method}` : shares.error));

  if (!shares.ok || !shares.shares?.length) {
    console.log('ABORT: sem shares — nao da para testar ACL');
    process.exit(1);
  }

  const share = shares.shares.find((s) => /atualiza-eduardo/i.test(s.name)) || shares.shares[0];
  console.log('share=', share.name, share.unc);

  let acl;
  try {
    acl = await getPathAcl(share.unc, {}, { localPath: share.localPath || '' });
  } catch (e) {
    acl = { ok: false, error: e.message };
  }

  const blob = JSON.stringify(acl);
  results.push(assert('getPathAcl sem ENAMETOOLONG', !/ENAMETOOLONG|spawn ENAMETOOLONG/i.test(blob), acl.ok ? acl.method : acl.error));
  results.push(assert('getPathAcl sem jargao WMI bruto', !/WMI ACL n|GetSecurityDescriptor|ManagementObject/i.test(acl.error || ''), acl.error || 'ok'));

  if (acl.ok) {
    results.push(assert('getPathAcl retornou entradas', (acl.entries || []).length >= 0, `count=${acl.count} method=${acl.method}`));
  } else {
    // Sem credencial AD, o esperado neste fileserver e Acesso negado amigavel
    results.push(assert(
      'erro amigavel (acesso/credencial)',
      /acesso negado|usuario e senha|usuário e senha|permiss/i.test(acl.error || ''),
      acl.error
    ));
  }

  // Stress: 3x ACL em paralelo nao pode quebrar por linha de comando
  const stress = await Promise.all([
    getPathAcl(share.unc, {}, { localPath: share.localPath || '' }),
    getPathAcl(share.unc, {}, { localPath: share.localPath || '' }),
    getPathAcl(share.unc, {}, { localPath: share.localPath || '' })
  ]);
  results.push(assert(
    'stress 3x sem ENAMETOOLONG',
    stress.every((r) => !/ENAMETOOLONG|spawn ENAMETOOLONG/i.test(JSON.stringify(r))),
    stress.map((r) => (r.ok ? r.method : 'err')).join(',')
  ));

  const kids = await listChildren(share.unc, {}, { localPath: share.localPath || '' });
  results.push(assert('listChildren sem ENAMETOOLONG', !/ENAMETOOLONG/i.test(JSON.stringify(kids)), kids.ok ? `count=${kids.count}` : kids.error));

  if (kids.ok && kids.children?.[0]) {
    const child = kids.children[0];
    const childAcl = await getPathAcl(child.unc, {}, { localPath: child.localPath || '' });
    results.push(assert(
      'ACL subpasta sem ENAMETOOLONG/WMI bruto',
      !/ENAMETOOLONG|WMI ACL n|GetSecurityDescriptor|ManagementObject/i.test(JSON.stringify(childAcl)),
      childAcl.ok ? childAcl.method : childAcl.error
    ));
  }

  const failed = results.filter((r) => !r.pass);
  console.log('--- SUMMARY ---', { total: results.length, fail: failed.length });
  if (failed.length) {
    console.log(failed);
    process.exit(1);
  }
  console.log('ALL TESTS PASSED');
  process.exit(0);
})().catch((e) => {
  console.error('CRASH', e);
  process.exit(2);
});

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

/**
 * Bridge JDBC para Oracle 11g usando ojdbc*.jar local (sem Instant Client 64-bit).
 * Entrada: arquivo JSON (caminho em args[0])
 * Saída: JSON em stdout
 */
public class OracleJdbcBridge {
  public static void main(String[] args) {
    try {
      if (args.length < 1) {
        fail("Uso: OracleJdbcBridge <request.json>");
        return;
      }
      String raw = new String(Files.readAllBytes(Paths.get(args[0])), StandardCharsets.UTF_8);
      Map<String, Object> req = parseFlatJson(raw);
      String action = str(req.get("action"));
      String url = str(req.get("url"));
      String user = str(req.get("user"));
      String password = str(req.get("password"));

      if (url.isEmpty() || user.isEmpty()) {
        fail("url/user obrigatórios");
        return;
      }

      Class.forName("oracle.jdbc.OracleDriver");
      try (Connection conn = DriverManager.getConnection(url, user, password)) {
        if ("test".equalsIgnoreCase(action)) {
          try (Statement st = conn.createStatement();
               ResultSet rs = st.executeQuery("SELECT 1 AS OK FROM DUAL")) {
            Map<String, Object> sample = null;
            if (rs.next()) sample = rowToMap(rs);
            okTest(sample);
          }
          return;
        }

        if ("query".equalsIgnoreCase(action)) {
          String sql = str(req.get("sql"));
          @SuppressWarnings("unchecked")
          List<String> binds = (List<String>) req.get("binds");
          if (binds == null) binds = Collections.emptyList();
          if (sql.isEmpty()) {
            fail("sql obrigatório");
            return;
          }
          try (PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < binds.size(); i++) {
              ps.setString(i + 1, binds.get(i));
            }
            try (ResultSet rs = ps.executeQuery()) {
              List<Map<String, Object>> rows = new ArrayList<Map<String, Object>>();
              while (rs.next()) rows.add(rowToMap(rs));
              okQuery(rows);
            }
          }
          return;
        }

        fail("action inválida: " + action);
      }
    } catch (Throwable t) {
      fail(t.getMessage() == null ? t.toString() : t.getMessage());
    }
  }

  static Map<String, Object> rowToMap(ResultSet rs) throws SQLException {
    ResultSetMetaData md = rs.getMetaData();
    int n = md.getColumnCount();
    Map<String, Object> row = new LinkedHashMap<String, Object>();
    for (int i = 1; i <= n; i++) {
      String label = md.getColumnLabel(i);
      Object val = rs.getObject(i);
      if (val == null) row.put(label, null);
      else if (val instanceof java.sql.Date || val instanceof java.sql.Timestamp || val instanceof java.util.Date)
        row.put(label, val.toString());
      else if (val instanceof Number || val instanceof Boolean) row.put(label, val);
      else row.put(label, String.valueOf(val));
    }
    return row;
  }

  static void okTest(Map<String, Object> sample) {
    StringBuilder sb = new StringBuilder();
    sb.append("{\"ok\":true,\"message\":\"Conexão Oracle OK (JDBC)\",\"driver\":\"jdbc\"");
    if (sample != null) {
      sb.append(",\"sample\":");
      sb.append(toJson(sample));
    }
    sb.append("}");
    System.out.println(sb.toString());
  }

  static void okQuery(List<Map<String, Object>> rows) {
    StringBuilder sb = new StringBuilder();
    sb.append("{\"ok\":true,\"driver\":\"jdbc\",\"count\":").append(rows.size()).append(",\"rows\":[");
    for (int i = 0; i < rows.size(); i++) {
      if (i > 0) sb.append(',');
      sb.append(toJson(rows.get(i)));
    }
    sb.append("]}");
    System.out.println(sb.toString());
  }

  static void fail(String msg) {
    System.out.println("{\"ok\":false,\"error\":" + quote(msg) + "}");
  }

  static String toJson(Map<String, Object> map) {
    StringBuilder sb = new StringBuilder();
    sb.append('{');
    boolean first = true;
    for (Map.Entry<String, Object> e : map.entrySet()) {
      if (!first) sb.append(',');
      first = false;
      sb.append(quote(e.getKey())).append(':');
      Object v = e.getValue();
      if (v == null) sb.append("null");
      else if (v instanceof Number || v instanceof Boolean) sb.append(String.valueOf(v));
      else sb.append(quote(String.valueOf(v)));
    }
    sb.append('}');
    return sb.toString();
  }

  static String quote(String s) {
    if (s == null) return "null";
    StringBuilder sb = new StringBuilder("\"");
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
